const daten = { ...$json };

const pflichtfelder = [
  'Kundenname',
  'Kunden_E-Mail',
  'Leistungsbeschreibung',
  'Gesamt_Netto'
];

const fehlendeFelder = pflichtfelder.filter(
  feld =>
    daten[feld] === undefined ||
    daten[feld] === null ||
    String(daten[feld]).trim() === ''
);

if (fehlendeFelder.length > 0) {
  throw new Error(
    `Folgende Pflichtfelder fehlen: ${fehlendeFelder.join(', ')}`
  );
}

function zahlEinlesen(wert, standardwert = 0) {
  if (wert === undefined || wert === null || wert === '') {
    return standardwert;
  }

  if (typeof wert === 'number') {
    return wert;
  }

  let text = String(wert)
    .trim()
    .replace(/\s/g, '')
    .replace(/€/g, '');

  if (text.includes(',') && text.includes('.')) {
    text = text.replace(/\./g, '').replace(',', '.');
  } else if (text.includes(',')) {
    text = text.replace(',', '.');
  }

  const zahl = Number(text);

  if (!Number.isFinite(zahl)) {
    throw new Error(`Ungültiger Zahlenwert: ${wert}`);
  }

  return zahl;
}

function deutschesDatum(datum) {
  return new Intl.DateTimeFormat('de-DE', {
    timeZone: 'Europe/Berlin',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  }).format(datum);
}

function datumEinlesen(wert, standardDatum) {
  if (
    wert === undefined ||
    wert === null ||
    String(wert).trim() === ''
  ) {
    return deutschesDatum(standardDatum);
  }

  if (wert instanceof Date && !Number.isNaN(wert.getTime())) {
    return deutschesDatum(wert);
  }

  const text = String(wert).trim();
  const seriennummer = Number(text.replace(',', '.'));

  // Google Sheets speichert Datumswerte intern als Seriennummern.
  if (
    Number.isFinite(seriennummer) &&
    seriennummer >= 20000 &&
    seriennummer <= 80000
  ) {
    const datum = new Date(
      Date.UTC(1899, 11, 30) +
      Math.floor(seriennummer) * 86400000
    );

    return deutschesDatum(datum);
  }

  const deutschesFormat =
    text.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);

  if (deutschesFormat) {
    const [, tag, monat, jahr] = deutschesFormat;

    return [
      tag.padStart(2, '0'),
      monat.padStart(2, '0'),
      jahr
    ].join('.');
  }

  const isoFormat =
    text.match(/^(\d{4})-(\d{2})-(\d{2})/);

  if (isoFormat) {
    const [, jahr, monat, tag] = isoFormat;
    return `${tag}.${monat}.${jahr}`;
  }

  const datum = new Date(text);

  if (!Number.isNaN(datum.getTime())) {
    return deutschesDatum(datum);
  }

  throw new Error(`Ungültiger Datumswert: ${wert}`);
}

const jetzt = new Date();
const nettobetrag = zahlEinlesen(daten.Gesamt_Netto);
const mwstProzent = zahlEinlesen(daten.MwSt_Prozent, 19);
const bruttobetrag = Number(
  (nettobetrag * (1 + mwstProzent / 100)).toFixed(2)
);

const jahr = new Intl.DateTimeFormat('de-DE', {
  timeZone: 'Europe/Berlin',
  year: 'numeric'
}).format(jetzt);

const kennung =
  daten.row_number !== undefined
    ? String(daten.row_number).padStart(4, '0')
    : String(Date.now()).slice(-6);

const gueltigBis = new Date(jetzt);
gueltigBis.setDate(gueltigBis.getDate() + 14);

daten.Angebotsnummer =
  daten.Angebotsnummer || `ANG-${jahr}-${kennung}`;

daten.Angebotsdatum =
  datumEinlesen(daten.Angebotsdatum, jetzt);

daten.Gesamt_Netto = nettobetrag;
daten.MwSt_Prozent = mwstProzent;
daten.Gesamt_Brutto = bruttobetrag;

daten.Gueltig_bis =
  datumEinlesen(daten.Gueltig_bis, gueltigBis);

daten.Zahlungsbedingungen =
  daten.Zahlungsbedingungen ||
  'Zahlbar innerhalb von 14 Tagen ohne Abzug.';

delete daten.row_number;
delete daten.change_type;

return {
  json: daten
};

const basisdaten =
  $('Angebotsdaten berechnen').item.json;

const angebotstext = String(
  $json.output || ''
).trim();

if (!angebotstext) {
  throw new Error(
    'Der KI-Agent hat keinen Angebotstext erstellt.'
  );
}

return {
  json: {
    ...basisdaten,
    Angebotstext: angebotstext,
    Status: 'ERSTELLT'
  }
};

const basis =
  $('Angebot zusammenfuehren').item.json;

return {
  json: {
    Angebotsnummer: basis.Angebotsnummer,
    Angebotsdatum: basis.Angebotsdatum,
    Kundenname: basis.Kundenname,
    'Kunden_E-Mail': basis['Kunden_E-Mail'],
    Strasse_Hausnummer: basis.Strasse_Hausnummer,
    PLZ: basis.PLZ,
    Ort: basis.Ort,
    Projektart: basis.Projektart,
    Leistungsbeschreibung: basis.Leistungsbeschreibung,
    Gesamt_Netto: basis.Gesamt_Netto,
    MwSt_Prozent: basis.MwSt_Prozent,
    Gesamt_Brutto: basis.Gesamt_Brutto,
    Gueltig_bis: basis.Gueltig_bis,
    Zahlungsbedingungen: basis.Zahlungsbedingungen,
    Status: basis.Status,
    Angebotstext: basis.Angebotstext,
    PDF_Link: $json.webViewLink
  }
};

const daten = $json;

function entitiesDekodieren(text) {
  const entities = {
    nbsp: ' ',
    amp: '&',
    lt: '<',
    gt: '>',
    quot: '"',
    apos: "'",
    auml: 'ä',
    Auml: 'Ä',
    ouml: 'ö',
    Ouml: 'Ö',
    uuml: 'ü',
    Uuml: 'Ü',
    szlig: 'ß',
    euro: '€',
    ndash: '–',
    mdash: '—'
  };

  let ergebnis = String(text);

  ergebnis = ergebnis.replace(
    /&#x([0-9a-f]+);/gi,
    (_, wert) => String.fromCodePoint(parseInt(wert, 16))
  );

  ergebnis = ergebnis.replace(
    /&#(\d+);/g,
    (_, wert) => String.fromCodePoint(parseInt(wert, 10))
  );

  // Zweimal ausführen, falls Zeichen doppelt codiert sind.
  for (let i = 0; i < 2; i++) {
    ergebnis = ergebnis.replace(
      /&([A-Za-z]+);/g,
      (treffer, name) => entities[name] ?? treffer
    );
  }

  return ergebnis;
}

function htmlZuText(inhalt) {
  return entitiesDekodieren(
    String(inhalt)
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const absenderObjekt = daten.from?.value?.[0];

const absenderText =
  daten.from?.text ||
  daten.From ||
  '';

const kundenEmail =
  absenderObjekt?.address ||
  absenderText.match(/<([^<>]+@[^<>]+)>/)?.[1] ||
  absenderText.match(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/)?.[0] ||
  '';

const absenderName =
  absenderObjekt?.name ||
  absenderText
    .replace(/<[^>]+>/g, '')
    .replace(/"/g, '')
    .trim();

const textVarianten = [
  typeof daten.text === 'string'
    ? htmlZuText(daten.text)
    : '',
  typeof daten.textAsHtml === 'string'
    ? htmlZuText(daten.textAsHtml)
    : '',
  typeof daten.html === 'string'
    ? htmlZuText(daten.html)
    : '',
  typeof daten.snippet === 'string'
    ? htmlZuText(daten.snippet)
    : ''
].filter(text => text.length > 0);

const anfrage =
  textVarianten.sort((a, b) => b.length - a.length)[0] || '';

if (!anfrage) {
  throw new Error(
    'In der E-Mail wurde kein Nachrichtentext gefunden.'
  );
}

const ergebnis = {
  json: {
    Gmail_Message_ID: daten.id || '',
    Gmail_Thread_ID: daten.threadId || '',
    Absender_Name: absenderName,
    'Kunden_E-Mail': kundenEmail,
    Betreff: daten.subject || daten.Subject || '',
    Anfrage: anfrage
  }
};

if ($binary && Object.keys($binary).length > 0) {
  ergebnis.binary = $binary;
}

return ergebnis;

