const vorhandeneAngebote = $input
  .all()
  .map(item => item.json);

const extrahiert =
  $('Angebotsdaten aus E-Mail extrahieren')
    .first()
    .json
    .output;

const emailDaten =
  $('E-Mail-Daten vorbereiten')
    .first()
    .json;

function textBereinigen(wert) {
  if (wert === undefined || wert === null) {
    return '';
  }

  return String(wert).trim();
}

const istLeistungsverzeichnis =
  extrahiert.PDF_Ist_Leistungsverzeichnis === true ||
  String(
    extrahiert.PDF_Ist_Leistungsverzeichnis
  ).toLowerCase() === 'true';

const beschreibungsTeile = [];

const normaleLeistungsbeschreibung =
  textBereinigen(
    extrahiert.Leistungsbeschreibung
  );

if (normaleLeistungsbeschreibung) {
  beschreibungsTeile.push(
    normaleLeistungsbeschreibung
  );
}

if (istLeistungsverzeichnis) {
  const lvLeistungen =
    textBereinigen(extrahiert.LV_Leistungen);

  const lvMaterialien =
    textBereinigen(extrahiert.LV_Materialien);

  const lvMengen =
    textBereinigen(extrahiert.LV_Mengen);

  if (lvLeistungen) {
    beschreibungsTeile.push(
      `Leistungen aus dem Leistungsverzeichnis:\n${lvLeistungen}`
    );
  }

  if (lvMaterialien) {
    beschreibungsTeile.push(
      `Materialien aus dem Leistungsverzeichnis:\n${lvMaterialien}`
    );
  }

  if (lvMengen) {
    beschreibungsTeile.push(
      `Mengen aus dem Leistungsverzeichnis:\n${lvMengen}`
    );
  }
}

const leistungsbeschreibung =
  beschreibungsTeile.join('\n\n');

const jahr = new Intl.DateTimeFormat('de-DE', {
  timeZone: 'Europe/Berlin',
  year: 'numeric'
}).format(new Date());

const nummernMuster =
  new RegExp(`^ANG-${jahr}-(\\d+)$`);

let hoechsteNummer = 0;

for (const angebot of vorhandeneAngebote) {
  const treffer = String(
    angebot.Angebotsnummer || ''
  ).match(nummernMuster);

  if (treffer) {
    hoechsteNummer = Math.max(
      hoechsteNummer,
      Number(treffer[1])
    );
  }
}

const naechsteNummer =
  String(hoechsteNummer + 1).padStart(4, '0');

return [
  {
    json: {
      Angebotsnummer:
        `ANG-${jahr}-${naechsteNummer}`,

      Angebotsdatum: '',

      Kundenname:
        textBereinigen(extrahiert.Kundenname),

      'Kunden_E-Mail':
        textBereinigen(
          emailDaten['Kunden_E-Mail']
        ),

      Strasse_Hausnummer:
        textBereinigen(
          extrahiert.Strasse_Hausnummer
        ),

      PLZ:
        textBereinigen(extrahiert.PLZ),

      Ort:
        textBereinigen(extrahiert.Ort),

      Projektart:
        textBereinigen(extrahiert.Projektart),

      Leistungsbeschreibung:
        leistungsbeschreibung,

      Gesamt_Netto: '',

      MwSt_Prozent: 19,

      Gesamt_Brutto: '',

      Gueltig_bis: '',

      Zahlungsbedingungen:
        'Zahlbar innerhalb von 14 Tagen ohne Abzug',

      Status: 'ENTWURF',

      Angebotstext: '',

      PDF_Link: ''
    }
  }
];

const eingang = $input.item;
const binaerdateien = eingang.binary ?? {};

const pdfDateien = Object.entries(binaerdateien).filter(
  ([feldname, datei]) => {
    const mimeType = String(datei.mimeType ?? '').toLowerCase();
    const dateiname = String(datei.fileName ?? '').toLowerCase();

    return (
      mimeType === 'application/pdf' ||
      dateiname.endsWith('.pdf')
    );
  }
);

const erstePDF = pdfDateien[0]?.[1];

const json = {
  ...eingang.json,
  Hat_PDF_Anhang: Boolean(erstePDF),
  PDF_Anzahl: pdfDateien.length,
  PDF_Dateiname: erstePDF?.fileName ?? ''
};

if (!erstePDF) {
  return {
    json,
    binary: binaerdateien
  };
}

return {
  json,
  binary: {
    ...binaerdateien,
    data: erstePDF
  }
};

const seitenzahl = Number($json.numpages ?? 0);
const hatPDF = Number.isFinite(seitenzahl) && seitenzahl > 0;

return {
  json: {
    Hat_PDF_Anhang: hatPDF,
    PDF_Text:
      hatPDF && typeof $json.text === 'string'
        ? $json.text.trim()
        : '',
    PDF_Seiten: hatPDF ? seitenzahl : 0,
    PDF_Titel:
      hatPDF && $json.info?.Title
        ? String($json.info.Title).trim()
        : ''
  }
};

const angebot = $json;

const extrahiert =
  $('Angebotsdaten aus E-Mail extrahieren')
    .item.json.output;

const emailDaten =
  $('E-Mail und PDF zusammenführen')
    .first()
    .json;

const anfragedatum = new Intl.DateTimeFormat('de-DE', {
  timeZone: 'Europe/Berlin',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric'
}).format(new Date());

const preisanfrageText = `Guten Tag,

bitte erstellen Sie uns für das folgende Projekt ein aktuelles, projektbezogenes Materialangebot.

Referenz: ${angebot.Angebotsnummer}
Projektart: ${angebot.Projektart}

Leistungen:
${extrahiert.LV_Leistungen || 'Keine Angaben vorhanden.'}

Benötigte Materialien:
${extrahiert.LV_Materialien || 'Keine Angaben vorhanden.'}

Mengen:
${extrahiert.LV_Mengen || 'Keine Angaben vorhanden.'}

Bitte berücksichtigen Sie unsere aktuell gültigen, mengenabhängigen Rabatte und teilen Sie uns Folgendes mit:

- aktuelle Netto-Einkaufspreise
- gewährte Rabatte
- Lieferkosten
- Lieferzeit und Verfügbarkeit
- Gültigkeitsdauer des Angebots

Die angegebenen Mengen sind projektbezogen. Bitte keine älteren Preise oder Rabattierungen übernehmen.

Vielen Dank.

Mit freundlichen Grüßen
FLOW AI Automation`;

return {
  json: {
    Preisanfrage_ID:
      `PA-${angebot.Angebotsnummer}`,

    Angebotsnummer:
      angebot.Angebotsnummer,

    Anfragedatum:
      anfragedatum,

    Grosshaendler: '',

    'Grosshaendler_E-Mail': '',

    Kundenname:
      angebot.Kundenname,

    Projektart:
      angebot.Projektart,

    LV_Leistungen:
      extrahiert.LV_Leistungen || '',

    LV_Materialien:
      extrahiert.LV_Materialien || '',

    LV_Mengen:
      extrahiert.LV_Mengen || '',

    Preisanfrage_Text:
      preisanfrageText,

    Status:
      'ENTWURF',

    Gmail_Thread_ID:
      emailDaten.Gmail_Thread_ID || '',

    Haendlerangebot_Link: ''
  }
};

const email = $input.first().json;

// Gmail-Header auslesen
const headers = email.payload?.headers || [];

const getHeader = (name) =>
  headers.find(
    (header) => header.name?.toLowerCase() === name.toLowerCase()
  )?.value || "";

// Base64-URL-Inhalt dekodieren
const decodeBody = (data) => {
  if (!data) return "";

  return Buffer.from(
    data.replace(/-/g, "+").replace(/_/g, "/"),
    "base64"
  ).toString("utf8");
};

// Nachrichtentext rekursiv aus Gmail-Struktur auslesen
const extractText = (part) => {
  if (!part) return "";

  if (part.mimeType === "text/plain" && part.body?.data) {
    return decodeBody(part.body.data);
  }

  if (Array.isArray(part.parts)) {
    for (const childPart of part.parts) {
      const text = extractText(childPart);
      if (text) return text;
    }
  }

  return "";
};

const betreff = getHeader("Subject") || email.subject || "";
const absender =
  getHeader("From") ||
  email.from?.text ||
  email.from?.value?.[0]?.address ||
  "";

const antwortText =
  extractText(email.payload) ||
  email.textPlain ||
  email.text ||
  email.snippet ||
  "";

const suchText = `${betreff}\n${antwortText}\n${email.snippet || ""}`;

const preisanfrageTreffer = suchText.match(/PA-ANG-\d{4}-\d+/i);
const angebotsTreffer = suchText.match(/ANG-\d{4}-\d+/i);

const preisanfrageId =
  preisanfrageTreffer?.[0]?.toUpperCase() ||
  (angebotsTreffer ? `PA-${angebotsTreffer[0].toUpperCase()}` : "");

const angebotsnummer =
  angebotsTreffer?.[0]?.toUpperCase() || "";

if (!preisanfrageId || !angebotsnummer) {
  throw new Error(
    "Preisanfrage_ID oder Angebotsnummer konnte in der Händlerantwort nicht gefunden werden."
  );
}

return [
  {
    json: {
      Preisanfrage_ID: preisanfrageId,
      Angebotsnummer: angebotsnummer,
      Grosshaendler_Absender: absender,
      Betreff: betreff,
      Haendlerantwort_Text: antwortText.trim(),
      Gmail_Thread_ID: email.threadId || "",
      Gmail_Message_ID: email.id || "",
      Antwortdatum: new Date(
        Number(email.internalDate) || Date.now()
      ).toLocaleDateString("de-DE"),
      Status: "ANTWORT_ERHALTEN"
    }
  }
];

const eingaben = $input.all().map(item => item.json);

if (eingaben.length === 0) {
  throw new Error(
    'Es wurden keine Händlerangebote für den Vergleich gefunden.'
  );
}

// Identische Händlerangebote anhand ihrer eindeutigen ID entfernen
const eindeutigeAngebote = new Map();

eingaben.forEach((angebot, index) => {
  const schluessel =
    String(
      angebot.Haendlerangebot_ID ||
      angebot.Gmail_Message_ID ||
      `OHNE-ID-${index}`
    ).trim();

  const vorhandenesAngebot =
    eindeutigeAngebote.get(schluessel);

  // Bei Dubletten die zuletzt gespeicherte Zeile verwenden
  if (
    !vorhandenesAngebot ||
    Number(angebot.row_number || 0) >
      Number(vorhandenesAngebot.row_number || 0)
  ) {
    eindeutigeAngebote.set(schluessel, angebot);
  }
});

const bereinigteEingaben =
  Array.from(eindeutigeAngebote.values());

// Deutsche und internationale Preisformate sicher einlesen
function preisEinlesen(wert) {
  if (
    wert === undefined ||
    wert === null ||
    wert === ''
  ) {
    return null;
  }

  if (typeof wert === 'number') {
    return Number.isFinite(wert) ? wert : null;
  }

  const text = String(wert).trim();

  const zahlen = text.match(
    /-?\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?|-?\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|-?\d+(?:,\d{1,2})|-?\d+(?:\.\d{1,2})|-?\d+/g
  ) || [];

  if (zahlen.length === 0) {
    return null;
  }

  // Bei „19% (198,97 €)“ wird der letzte Wert genommen
  let zahlText = zahlen[zahlen.length - 1]
    .replace(/\s/g, '');

  if (
    zahlText.includes('.') &&
    zahlText.includes(',')
  ) {
    if (
      zahlText.lastIndexOf(',') >
      zahlText.lastIndexOf('.')
    ) {
      // Deutsches Format: 1.246,17
      zahlText = zahlText
        .replace(/\./g, '')
        .replace(',', '.');
    } else {
      // Internationales Format: 1,246.17
      zahlText = zahlText.replace(/,/g, '');
    }
  } else if (zahlText.includes(',')) {
    zahlText = zahlText.replace(',', '.');
  } else if (zahlText.includes('.')) {
    const teile = zahlText.split('.');

    const istTausenderformat =
      teile.length >= 2 &&
      teile[teile.length - 1].length === 3 &&
      teile.slice(1).every(
        teil => teil.length === 3
      ) &&
      teile[0].length <= 3;

    if (istTausenderformat) {
      zahlText = zahlText.replace(/\./g, '');
    }
  }

  const zahl = Number(zahlText);

  return Number.isFinite(zahl) ? zahl : null;
}

function lieferzeitEinlesen(wert) {
  const zahlen =
    String(wert || '')
      .match(/\d+/g)
      ?.map(Number) || [];

  return {
    minimum:
      zahlen.length >= 1 ? zahlen[0] : null,

    maximum:
      zahlen.length >= 2
        ? zahlen[1]
        : zahlen.length === 1
          ? zahlen[0]
          : null
  };
}

const preisanfrageId =
  String(
    bereinigteEingaben[0].Preisanfrage_ID || ''
  ).trim();

if (!preisanfrageId) {
  throw new Error(
    'Die Preisanfrage_ID fehlt in den Händlerangeboten.'
  );
}

const unterschiedlicheIds =
  bereinigteEingaben.filter(
    angebot =>
      String(
        angebot.Preisanfrage_ID || ''
      ).trim() !== preisanfrageId
  );

if (unterschiedlicheIds.length > 0) {
  throw new Error(
    'Die Händlerangebote gehören nicht alle zur selben Preisanfrage_ID.'
  );
}

const angebote = bereinigteEingaben.map(
  angebot => {
    const lieferzeit =
      lieferzeitEinlesen(angebot.Lieferzeit);

    return {
      row_number: angebot.row_number,

      Haendlerangebot_ID:
        angebot.Haendlerangebot_ID || '',

      Preisanfrage_ID:
        angebot.Preisanfrage_ID || '',

      Angebotsnummer:
        angebot.Angebotsnummer || '',

      Haendlername:
        angebot.Haendlername ||
        'Nicht angegeben',

      Grosshaendler_Absender:
        angebot.Grosshaendler_Absender || '',

      Gesamtpreis_netto:
        preisEinlesen(
          angebot.Gesamtpreis_netto
        ),

      Mehrwertsteuer:
        preisEinlesen(
          angebot.Mehrwertsteuer
        ),

      Gesamtpreis_brutto:
        preisEinlesen(
          angebot.Gesamtpreis_brutto
        ),

      Lieferkosten:
        preisEinlesen(
          angebot.Lieferkosten
        ),

      Lieferzeit:
        angebot.Lieferzeit ||
        'Nicht angegeben',

      Lieferzeit_min_Tage:
        lieferzeit.minimum,

      Lieferzeit_max_Tage:
        lieferzeit.maximum,

      Gueltig_bis:
        angebot.Gueltig_bis ||
        'Nicht angegeben',

      Zahlungsbedingungen:
        angebot.Zahlungsbedingungen ||
        'Nicht angegeben',

      Positionen:
        angebot.Positionen ||
        'Nicht angegeben',

      Hinweise:
        angebot.Hinweise || '',

      Zusammenfassung:
        angebot.Zusammenfassung || ''
    };
  }
);

angebote.sort((a, b) => {
  const preisA =
    a.Gesamtpreis_brutto ??
    Number.POSITIVE_INFINITY;

  const preisB =
    b.Gesamtpreis_brutto ??
    Number.POSITIVE_INFINITY;

  if (preisA !== preisB) {
    return preisA - preisB;
  }

  const lieferzeitA =
    a.Lieferzeit_max_Tage ??
    Number.POSITIVE_INFINITY;

  const lieferzeitB =
    b.Lieferzeit_max_Tage ??
    Number.POSITIVE_INFINITY;

  return lieferzeitA - lieferzeitB;
});

return [
  {
    json: {
      Preisanfrage_ID: preisanfrageId,

      Anzahl_Angebote: angebote.length,

      Entfernte_Dubletten:
        eingaben.length -
        bereinigteEingaben.length,

      Vergleich_bereit:
        angebote.length >= 2,

      Vergleichsstatus:
        angebote.length >= 2
          ? 'BEREIT_ZUM_VERGLEICH'
          : 'WEITERES_ANGEBOT_ERFORDERLICH',

      Angebote: angebote,

      Angebote_JSON:
        JSON.stringify(angebote, null, 2)
    }
  }
];

const eingabe = $input.first().json;

// KI-Ergebnis aus der OpenAI-Ausgabe holen
let ergebnis =
  eingabe.output?.[0]?.content?.[0]?.text ??
  eingabe.text ??
  eingabe;

// Falls das Modell JSON als Text zurückgibt
if (typeof ergebnis === 'string') {
  const bereinigterText = ergebnis
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    ergebnis = JSON.parse(bereinigterText);
  } catch (error) {
    throw new Error(
      `Das KI-Vergleichsergebnis ist kein gültiges JSON: ${error.message}`
    );
  }
}

if (!ergebnis || typeof ergebnis !== 'object') {
  throw new Error(
    'Das KI-Vergleichsergebnis konnte nicht verarbeitet werden.'
  );
}

const preisanfrageId =
  String(ergebnis.Preisanfrage_ID || '').trim();

const bestesAngebotId =
  String(ergebnis.Bestes_Haendlerangebot_ID || '').trim();

if (!preisanfrageId) {
  throw new Error(
    'Im KI-Vergleichsergebnis fehlt die Preisanfrage_ID.'
  );
}

if (!bestesAngebotId) {
  throw new Error(
    'Im KI-Vergleichsergebnis fehlt die Bestes_Haendlerangebot_ID.'
  );
}

// Ursprünglich verglichene Angebote laden
const vergleichsdaten =
  $('Händlerangebote für Vergleich vorbereiten')
    .first()
    .json;

const angebote =
  Array.isArray(vergleichsdaten.Angebote)
    ? vergleichsdaten.Angebote
    : [];

if (angebote.length < 2) {
  throw new Error(
    'Für die Tabellenaktualisierung wurden weniger als zwei Angebote gefunden.'
  );
}

const bestesAngebotGefunden =
  angebote.some(
    angebot =>
      String(angebot.Haendlerangebot_ID || '').trim() ===
      bestesAngebotId
  );

if (!bestesAngebotGefunden) {
  throw new Error(
    `Das beste Händlerangebot ${bestesAngebotId} ist nicht in den verglichenen Angeboten enthalten.`
  );
}

// Aktualisierungen für jede Angebotszeile vorbereiten
const angeboteAktualisierungen =
  angebote.map(angebot => {
    const angebotId =
      String(
        angebot.Haendlerangebot_ID || ''
      ).trim();

    const istBestesAngebot =
      angebotId === bestesAngebotId;

    return {
      Haendlerangebot_ID: angebotId,
      Preisanfrage_ID: preisanfrageId,
      Vergleichsstatus: 'VERGLICHEN',
      Ist_bestes_Angebot: istBestesAngebot,

      KI_Empfehlung: istBestesAngebot
        ? String(
            ergebnis.KI_Empfehlung ||
            ergebnis.Begruendung ||
            ''
          )
        : `Nicht ausgewählt. Empfohlen wird ${
            ergebnis.Bester_Haendlername ||
            bestesAngebotId
          }.`
    };
  });

return [
  {
    json: {
      Preisanfrage_ID: preisanfrageId,

      Bestes_Haendlerangebot_ID:
        bestesAngebotId,

      Bester_Haendlername:
        ergebnis.Bester_Haendlername ||
        'Nicht angegeben',

      Bester_Gesamtpreis_brutto:
        ergebnis.Bester_Gesamtpreis_brutto ??
        null,

      Bester_Gesamtpreis_netto:
        ergebnis.Bester_Gesamtpreis_netto ??
        null,

      Bester_Lieferkosten:
        ergebnis.Bester_Lieferkosten ??
        null,

      Bester_Lieferzeit:
        ergebnis.Bester_Lieferzeit ||
        'Nicht angegeben',

      Bester_Zahlungsbedingungen:
        ergebnis.Bester_Zahlungsbedingungen ||
        'Nicht angegeben',

      Anzahl_verglichener_Angebote:
        Number(
          ergebnis.Anzahl_verglichener_Angebote ||
          angebote.length
        ),

      Preisunterschied_zum_teuersten_Angebot:
        ergebnis.Preisunterschied_zum_teuersten_Angebot ??
        null,

      Preisvergleich:
        ergebnis.Preisvergleich || '',

      Lieferzeitvergleich:
        ergebnis.Lieferzeitvergleich || '',

      Begruendung:
        ergebnis.Begruendung || '',

      KI_Empfehlung:
        ergebnis.KI_Empfehlung || '',

      Status: 'ANGEBOTE_VERGLICHEN',

      Vergleichsstatus:
        'ANGEBOTE_VERGLICHEN',

      Anzahl_Aktualisierungen:
        angeboteAktualisierungen.length,

      Angebote_Aktualisierungen:
        angeboteAktualisierungen
    }
  }
];

const ergebnis = $input.first().json;

const aktualisierungen =
  ergebnis.Angebote_Aktualisierungen;

if (
  !Array.isArray(aktualisierungen) ||
  aktualisierungen.length === 0
) {
  throw new Error(
    'Es wurden keine Angebotsaktualisierungen gefunden.'
  );
}

return aktualisierungen.map(
  aktualisierung => ({
    json: aktualisierung
  })
);

const daten = $input.first().json;

return [
  {
    json: {
      Preisanfrage_ID: daten.Preisanfrage_ID,
      Bestes_Haendlerangebot_ID: daten.Bestes_Haendlerangebot_ID,
      Bester_Haendlername: daten.Bester_Haendlername,
      Bester_Gesamtpreis_netto: daten.Bester_Gesamtpreis_netto,
      Bester_Gesamtpreis_brutto: daten.Bester_Gesamtpreis_brutto,
      Bester_Lieferkosten: daten.Bester_Lieferkosten,
      Bester_Lieferzeit: daten.Bester_Lieferzeit,
      Bester_Zahlungsbedingungen: daten.Bester_Zahlungsbedingungen,
      Anzahl_verglichener_Angebote: daten.Anzahl_verglichener_Angebote,
      Preisunterschied_zum_teuersten_Angebot:
        daten.Preisunterschied_zum_teuersten_Angebot,
      Preisvergleich: daten.Preisvergleich,
      Lieferzeitvergleich: daten.Lieferzeitvergleich,
      Begruendung: daten.Begruendung,
      KI_Empfehlung: daten.KI_Empfehlung,
      Vergleichsstatus: daten.Vergleichsstatus
    }
  }
];
